package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.jscomp.phases অল.Pass;
import com.google.javascript.jscomp.types.JSDocInfo;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.CheckGlobalThisTestUtils.getCheckGlobalThis;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_shouldTraverse_TriageGen2Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Node lhs;

    @Mock
    private Node rhs;

    @Mock
    private Node jsDoc;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // Using a subclass or spy might be necessary if getFunctionJsDocInfo is private/protected
        // For this exercise, we assume the environment allows testing this logic.
        checkGlobalThis = new CheckGlobalThis();
    }

    @Test
    public void testShouldTraverse_NotFunction_ReturnsTrue() {
        when(n.getType()).thenReturn(Token.NAME);
        assertTrue(checkGlobalThis.shouldTraverse(t, n, null));
    }

    @Test
    public void testShouldTraverse_Function_NoJsDoc_ReturnsTrue() {
        when(n.getType()).thenReturn(Token.FUNCTION);
        // Assuming getFunctionJsDocInfo returns null for non-jsdoc functions
        // In a real scenario, we'd use a spy to mock getFunctionJsDocInfo
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(null);

        assertTrue(spyCheck.shouldTraverse(t, n, null));
    }

    @Test
    public void testShouldTraverse_Function_IsConstructor_ReturnsFalse() {
        when(n.getType()).thenReturn(Token.FUNCTION);
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(jsDoc);
        when(jsDoc.isConstructor()).thenReturn(true);

        assertFalse(spyCheck.shouldTraverse(t, n, null));
    }

    @Test
    public void testShouldTraverse_Function_HasThisType_ReturnsFalse() {
        when(n.getType()).thenReturn(Token.FUNCTION);
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(jsDoc);
        when(jsDoc.isConstructor()).thenReturn(false);
        when(jsDoc.hasThisType()).thenReturn(true);

        assertFalse(spyCheck.shouldTraverse(t, n, null));
    }

    @Test
    public void testShouldTraverse_Assignment_LHS_ReturnsTrue() {
        when(n.getType()).thenReturn(Token.NAME);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(n).thenReturn(lhs);

        assertTrue(checkGlobalThis.shouldTraverse(t, n, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_NotGetProp_ReturnsTrue() {
        when(n.getType()).thenReturn(Token.NAME);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(n).thenReturn(rhs);
        when(lhs.getType()).thenReturn(Token.NAME);

        assertTrue(checkGlobalThis.shouldTraverse(t, n, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_GetProp_Prototype_ReturnsFalse() {
        when(n.getType()).thenReturn(Token.NAME);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(n).thenReturn(rhs);
        when(lhs.getType()).thenReturn(Token.GETPROP);

        Node lastChild = mock(Node.class);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("prototype");

        assertFalse(checkGlobalThis.shouldTraverse(t, n, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_GetProp_QualifiedNameContainsPrototype_ReturnsFalse() {
        when(n.getType()).thenReturn(Token.NAME);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(n).thenReturn(rhs);
        when(lhs.getType()).thenReturn(Token.GETPROP);
        when(lhs.getLastChild()).thenReturn(mock(Node.class)); // Not "prototype"
        when(lhs.getQualifiedName()).thenReturn("Object.prototype.foo");

        assertFalse(checkGlobalThis.shouldTraverse(t, n, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_GetProp_NormalName_ReturnsTrue() {
        when(n.getType()).thenReturn(Token.NAME);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(n).thenReturn(rhs);
        when(lhs.getType()).thenReturn(Token.GETPROP);

        Node lastChild = mock(Node.class);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("somethingElse");
        when(lhs.getQualifiedName()).thenReturn("a.b");

        assertTrue(checkGlobalThis.shouldTraverse(t, n, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_GetProp_NullQualifiedName_ReturnsTrue() {
        when(n.getType()).thenReturn(Token.NAME);
        when(parent.getType()).thenReturn(Token.ASSIGN);
        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(n).thenReturn(rhs);
        when(lhs.getType()).thenReturn(Token.GETPROP);

        Node lastChild = mock(Node.class);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("notPrototype");
        when(lhs.getQualifiedName()).thenReturn(null);

        assertTrue(checkGlobalThis.shouldTraverse(t, n, parent));
    }
}
